import sys

sys.path.insert(0, "/workspace/task/source")

import numpy as np
import quimb.tensor as qtn

for seed, n, D, deg in [(11, 3, 2, 2), (3, 4, 2, 2), (5, 4, 3, 3), (7, 5, 3, 3)]:
    psi = qtn.TN_rand_tree(n=n, D=D, phys_dim=2, max_degree=deg, seed=seed)
    psi.equalize_norms_(1.0)
    Z_true = float(psi.norm() ** 2)
    gauges = {}
    psi.gauge_all_simple_(max_iterations=800, tol=1e-13, gauges=gauges)
    g2 = {k: (v / np.linalg.norm(v)).copy() for k, v in gauges.items()}

    tid2site = psi._get_tid_to_site_map()

    def site_norm(site, p):
        # || t x g^p per ket leg ||^2
        t = psi[psi.site_tag(site)]
        tg = t.copy()
        for ix in t.inds:
            if ix in psi._inner_inds:
                tg.multiply_index_diagonal_(ix, g2[ix] ** p)
        return float(np.sum(np.abs(tg.data) ** 2))

    for p in (0.5, 1.0):
        prod = np.prod([site_norm(s, p) for s in psi.sites])
        print(f"n={n},D={D},deg={deg},seed={seed} p={p}: prod/Z = {prod/Z_true:.6e}  (prod={prod:.6e}, Z={Z_true:.6e})")
